function firstPrefixedWord(sentence: string, term: string): number {
  const n = sentence.length, m = term.length;
  let i = 0, word = 1;
  while (i < n) {
    let j = 0;
    while (j < m && i + j < n && sentence[i + j] === term[j]) j++;
    if (j === m) return word;
    while (i < n && sentence[i] !== " ") i++;
    i++; // step past the space
    word++;
  }
  return -1;
}

