class Solution:
    def firstPrefixedWord(self, sentence: str, term: str) -> int:
        n, m = len(sentence), len(term)
        i, word = 0, 1
        while i < n:
            j = 0
            while j < m and i + j < n and sentence[i + j] == term[j]:
                j += 1
            if j == m:
                return word
            while i < n and sentence[i] != " ":
                i += 1
            i += 1  # step past the space
            word += 1
        return -1

